// TH14 synthetic training vocabulary (see transcribe/th14/touhou-bullets.ecl).
// Only the shapes used by this card are copied; source type maps to the alias below.
const TH14_RICE: int = 480;          // source type 8, radius 2.4, colors 0..15
const TH14_INVERT_RICE: int = 592;   // source type 15, radius 2.4, colors 0..15

// TH14 v1.00b st06mbs::MBoss1 (lines47-81) + dependency MBoss1_at (83-139).
// Entry state from MBoss:8-37: HP11000, hurtbox/hitbox 48x48 -> radius 24, position (0,128),
// moveLimit(0,128,280,64). Source timerReset at MBoss1:49; source timer 1500 -> MBoss2, not started.
// Source t0 starts the MBoss1_216 loop; first wave at source t=60. Card keeps the 120-frame
// opening buffer inside the phase, runs the source window to 1500, then lets tail bullets fly.
const TIME_LIMIT: int = 1924;
const SOURCE_LIMIT: int = 1500;
const OPENING_BUFFER: int = 120;

// Source EX chain from MBoss1_at:101-119. Birth ANIM/PLAYSOUND dropped by shared policy.
//   index1 VELTIME a30: scalar 2.0 -> 1.0, direction kept
//   index2 SETSPRITE type8 color2
//   index4 VELTIME a40: 1.0 -> 3.0
//   index5 ANGLE_ACCEL a40 async=1: angle += spin/frame, speed delta 0
//   index6 SETSPRITE type15 color2
//   index8 VELTIME a60: 3.0 -> 0.6; async=0 holds while ANGLE_ACCEL is active, so it starts
//           after index5 finishes. Scalar speed and angle stay parallel here, so set_accel
//           along the current angle matches VELTIME's saved-direction ramp.
xformdef MB1_RICE(spin: angle) {
    @30 set_accel(-0.0333333fx);
    set_accel(0fx);
    set_sprite(TH14_RICE, 2);
    @40 set_accel(0.05fx);
    set_accel(0fx);
    set_sprite(TH14_INVERT_RICE, 2);
    @40 set_ang_vel(spin);
    set_ang_vel(0deg);
    @60 set_accel(-0.04fx);
    set_accel(0fx);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var until: int = $frame+SOURCE_LIMIT;
    var rank: int = global(GVAR_RANK);
    // MBoss1_at:89-97 etCount: !E16 !N30 !H35 !LO40.
    var n: int = 16;
    if rank == 1 { n = 30; }
    if rank == 2 { n = 35; }
    if rank >= 3 { n = 40; }
    // MBoss1:63-72 wait: !E60 !N60 !H30 !LO20.
    var dwait: int = 60;
    if rank == 2 { dwait = 30; }
    if rank >= 3 { dwait = 20; }

    // MBoss1_at:86-100; etNew once per at() call, values identical every cycle.
    sh_reset(0);
    sh_sprite(0, TH14_INVERT_RICE, 2); // etSprite(0,15,2)
    sh_ring(0, 1);                     // etAim(0,3): fixed-direction full ring
    sh_aim(0, 0);
    sh_count(0, n, 1);                 // etCount(0,N,1)
    sh_speed(0, 2fx, 0fx);             // etSpeed(0,2,1); one layer uses s0

    var i0: int = 10; // MBoss1:53 $I0
    loop {
        if $frame >= until { return; }
        card_wait(60);                     // MBoss1:58
        var base: int = rand(65536)-32768; // MBoss1_at:120 %A = RANDRAD (-pi..pi)
        var dist: fx = 96fx;               // MBoss1_at:121
        var spin: int = 182;               // MBoss1_at:122 %C = 0.017453 rad ~ +1deg/frame
        var d6: int = 1092;                // MBoss1_at:123 %D = 0.10472 rad ~ 6deg
        var e: int = i0;                   // MBoss1_at:124 $E = $I0
        for k in 0..e {
            if $frame >= until { return; }
            sh_angle(0, base as angle, 0deg);  // :128
            // :129 etDist; ANIM a1 retreat position -= 4*initial speed along bullet angle.
            sh_dist(0, dist-8fx);
            sh_xform(0, MB1_RICE(spin as angle)); // :127 etExSet index5 spin
            sh_fire(0);                        // :134 etOn
            base = base+d6;                    // :130
            dist = dist-8fx;                   // :131
            spin = -spin;                      // :132
            d6 = -d6;                          // :133
            card_wait(3);                      // :135
        }
        card_wait(10);   // MBoss1:61
        card_wait(dwait); // MBoss1:63-72
        card_move_rand(); // MBoss1:75 moveRand(60,4,1.0)
        i0 = i0+1;        // MBoss1:76
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);  // MBoss:22 setHitbox(48,48), ordinary circle width*0.5
    set_hurtbox(24fx); // MBoss:21 setHurtbox(48,48)
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 11000, 0, 0, 0, boss_main); // MBoss:24 HP11000; movePosTime target (0,128)
    loop { wait(600); }
}

// TH14 v1.00b st06mbs::MBoss1 moveRand(60,4,1.0) helper.
// Same recipe as transcribe/th16/movement.md; only the moveLimit bounds differ:
// source moveLimit(0,128,280,64) -> x in [-140,140], y in [96,160]; inner region x +-70, y 112..144.
// int slot0 = next-step count; fx slots0/1 = logical unit vector.
// Every source wait inside this attack goes through card_wait in the same owner task.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx / 60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source = signed unit random * pi. Values below are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately do not normalize this branch before the source fabs tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05rad, nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}
